import { el, card, button, alertBox, modal, badge, spinner } from '../core/dom.js';
import { connectInstance, logoutInstance, restartInstance } from '../api/instances.js';
import { loadSession } from '../core/session.js';
import { pageHeader, instanceShell } from '../components/shell.js';
export function renderDashboard(instance,reloadInstance){const session=loadSession();const page=el('div',{class:'page'});const error=el('div');async function run(kind){error.replaceChildren();try{if(kind==='restart')await restartInstance(session,instance);if(kind==='logout')await logoutInstance(session,instance);if(kind==='qr'){const data=await connectInstance(session,instance,false);showQr(data)}if(kind==='pair'){const data=await connectInstance(session,instance,true);showPair(data)}await reloadInstance()}catch(e){error.replaceChildren(alertBox(e.message))}}function showQr(data){const code=data?.base64||data?.qrcode?.base64||data?.code||data?.qrcode?.code||'';const content=el('div',{class:'qr-wrap'});if(String(code).startsWith('data:image'))content.append(el('img',{src:code,alt:'QR Code'}));else content.append(el('pre',{class:'qr-text',text:code||'QR Code não retornado pela API'}));modal('QR Code',content)}function showPair(data){const code=data?.pairingCode||data?.qrcode?.pairingCode||data?.code||'';modal('Código de pareamento',el('div',{class:'pairing-code',text:code||'Código não retornado'}))}page.append(pageHeader(instance.name,instance.profileName||instance.ownerJid||'Aguardando conexão',[badge(instance.connectionStatus)]),error,card(el('div',{class:'dashboard-row'},el('div',{},el('span',{class:'muted',text:'Token da instância'}),el('code',{class:'token-line',text:instance.token||''})),el('div',{class:'actions'},button('Atualizar',{onclick:reloadInstance}),button('Reiniciar',{onclick:()=>run('restart')}),button('Desconectar',{class:'danger',onclick:()=>run('logout')}))),instance.connectionStatus!=='open'?el('div',{class:'connect-panel'},el('strong',{text:'Conecte o WhatsApp desta instância'}),el('div',{class:'actions'},button('Gerar QR Code',{class:'primary',onclick:()=>run('qr')}),instance.number?button('Código de pareamento',{onclick:()=>run('pair')}):null)):null),el('div',{class:'metric-grid'},metric('Contatos',instance._count?.Contact,'☷'),metric('Chats',instance._count?.Chat,'◉'),metric('Mensagens',instance._count?.Message,'✉')));return instanceShell(instance,'dashboard',page)}function metric(label,value,icon){return card(el('span',{class:'metric-icon',text:icon}),el('strong',{text:Number(value||0).toLocaleString('pt-BR')}),el('span',{text:label}))}
